"use strict";
const $ = jQuery;

// Smooth Scroll Function
function smoothScroll(e, t = 0) {
    const o = document.querySelector(e === "#" || e === "" ? "html" : e);
    if (!o) {
        console.log(e + " is not found.");
        return;
    }
    const r = Math.floor(window.pageYOffset + o.getBoundingClientRect().top - t);
    window.scrollTo({ top: r, behavior: "smooth" });
}

// Anchor Links for Smooth Scroll
const headerSelector = "#header";
const anchorLinks = document.querySelectorAll('a[href*="#"]:not(.no-move):not([target="_blank"])');
for (let e of anchorLinks) e.addEventListener("click", function (t) {
    const o = this.getAttribute("href");
    const r = o.replace(/#.*/gi, "");
    if (r !== "" && r !== location.href && r !== "./" && r !== location.pathname) return;
    t.preventDefault();
    const l = o.replace(/.*#/gi, "#");
    smoothScroll(l, headerSelector);
}, !1);

// Toggle Scroll Lock Function
function toggleScrollLock(e = !0) {
    const t = document.body;
    if (e) {
        const o = window.pageYOffset;
        t.style.position = "fixed";
        t.style.top = `-${o}px`;
        t.style.overflowY = "scroll";
        t.dataset.scrollLockTop = o;
    } else {
        const o = t.dataset.scrollLockTop || 0;
        t.style.position = "";
        t.style.top = "";
        t.style.overflowY = "";
        window.scrollTo({ top: o });
    }
}

// jQuery Code for Mobile Menu
$(function () {
    let e = "sp-menu";
    $("#sp-menu-open").on("click", function (t) {
        const o = $("#sp-menu-acc").hasClass("active");
        if (o) {
            $("#sp-menu-open").addClass("active");
            $("body").addClass("modalOn");
            $(".l-header").addClass("active");
            toggleScrollLock(!0);
        } else {
            $("#sp-menu-open").removeClass("active");
            $("body").removeClass("modalOn");
            $(".l-header").removeClass("active");
            toggleScrollLock(!1);
        }
    });

    $("#overlay").on("click", function () {
        $("#sp-menu-acc").removeClass("active");
        $("#sp-menu-open").removeClass("active");
        $("body").removeClass("modalOn");
        $(".l-header").removeClass("active");
        toggleScrollLock(!1);
    });
});

// Fixed Header on Scroll
let xi = document.querySelector(".l-header");
document.addEventListener("scroll", function () {
    let e = window.scrollY;
    xi && e >= 100 ? xi.classList.add("fixed") : xi && xi.classList.remove("fixed");
});